    reasons.push("低薪 -1");
  } else if (factors.wageLevel === "high") {
    change += 1;
    reasons.push("优厚工资 +1");
  }
  if (factors.hungryHouseholds > 0) {
    change -= 3;
    reasons.push("缺粮 -3");
