describe("税务署道路覆盖与国库集成", () => {
  it("重税命令保存后，连路税务署按月征税并扣除工资", () => {
    const world = hydrateWorld(citySnapshot(true));
    const policy = applyCommand(world, {
      seq: 1,
      type: "set-tax-rate",
      taxRate: "high",
    });
    expect(policy.result.accepted).toBe(true);

    const tick = applyCommand(world, {
      seq: 2,
      type: "advance-time",
      ticks: 1,
    });
    expect(tick.result.accepted).toBe(true);
    expect(snapshotWorld(world).economy).toEqual({
      treasury: 499,
      taxRate: "high",
      lastTaxRevenue: 3,
      lastPayroll: 4,
      taxableHouses: 1,
      sentiment: 49,
      lastTradeRevenue: 0,
    });
  });

  it("断路时不征幽灵税，但已分配官吏工资仍真实支出", () => {
    const world = hydrateWorld(citySnapshot(false));
    applyCommand(world, { seq: 1, type: "advance-time", ticks: 1 });
    expect(snapshotWorld(world).economy).toMatchObject({
      treasury: 496,
      lastTaxRevenue: 0,
      lastPayroll: 4,
      taxableHouses: 0,
    });
  });

  it("税率、累计国库和上月收支可随快照恢复", () => {
    const world = hydrateWorld(citySnapshot(true));
    applyCommand(world, { seq: 1, type: "advance-time", ticks: 1 });
    const restored = hydrateWorld(snapshotWorld(world));
    expect(snapshotWorld(restored).economy).toEqual(
      snapshotWorld(world).economy,
    );
  });
});

import type {
  CropType,
  LaborPolicyView,
  LaborSector,
  WageLevel,
} from "@empire/protocol";
import { cropPhaseAtTick } from "./crop-calendar";

export type LaborPolicy = LaborPolicyView;

export const DEFAULT_LABOR_POLICY: LaborPolicy = {
  wageLevel: "standard",
  priorities: ["agriculture", "commerce", "services"],
};

interface LaborCityView {
  tick: number;
  buildings: Array<{ typeId: string; cropType?: CropType }>;
  households: Array<{ residents: number }>;
}

export interface LaborReport {
  population: number;
  availableWorkers: number;
  demand: Record<LaborSector, number>;
  assigned: Record<LaborSector, number>;
  vacancies: Record<LaborSector, number>;
  payroll: number;
}

const PARTICIPATION_RATE: Record<WageLevel, number> = {
  low: 0.3,
  standard: 0.4,
  high: 0.5,
};

const WAGE_RATE: Record<WageLevel, number> = {
  low: 1,
  standard: 2,
  high: 3,
};

const MIGRATION_WAGE_MODIFIER: Record<WageLevel, number> = {
  low: -20,
  standard: 0,
  high: 20,
};

export function migrationAttractiveness(
  sentiment: number,
  wageLevel: WageLevel,
): { score: number; wageModifier: number; canMigrate: boolean } {
  const wageModifier = MIGRATION_WAGE_MODIFIER[wageLevel];
  const score = Math.max(0, Math.min(100, sentiment + wageModifier));
  return { score, wageModifier, canMigrate: score >= 40 };
}

export function calculateLaborReport(
  city: LaborCityView,
  policy: LaborPolicy,
): LaborReport {
  const population = city.households.reduce(
    (total, household) => total + household.residents,
    0,
  );
  const availableWorkers = Math.floor(
    population * PARTICIPATION_RATE[policy.wageLevel],
  );
  const demand: Record<LaborSector, number> = {
    agriculture: city.buildings.reduce(
      (total, building) =>
        (building.typeId === "farm" &&
          building.cropType !== undefined &&
          cropPhaseAtTick(building.cropType, city.tick) !== "dormant") ||
        (building.typeId === "hemp-farm" &&
          (city.tick % 12) + 1 >= 4 &&
          (city.tick % 12) + 1 <= 9)
          ? total + 2
          : total,
      0,
    ),
    commerce: city.buildings.reduce(
      (total, building) =>
        building.typeId === "granary" ||
        building.typeId === "market" ||
        building.typeId === "weaver" ||
        building.typeId === "weaponsmith" ||
        building.typeId === "trading-post"
          ? total + 1
          : total,
      0,
    ),
    services: city.buildings.reduce(
      (total, building) =>
        building.typeId === "infantry-fort" || building.typeId === "tax-office"
          ? total + 2
          : building.typeId === "music-school"
            ? total + 1
            : building.typeId === "well"
              ? total + 1
              : total,
      0,
    ),
  };
  const assigned: Record<LaborSector, number> = {
    agriculture: 0,
    commerce: 0,
    services: 0,
  };
  let remaining = availableWorkers;
  for (const sector of policy.priorities) {
    assigned[sector] = Math.min(demand[sector], remaining);
    remaining -= assigned[sector];
  }
  const vacancies = {
    agriculture: demand.agriculture - assigned.agriculture,
    commerce: demand.commerce - assigned.commerce,
    services: demand.services - assigned.services,
  };
  const assignedWorkers = Object.values(assigned).reduce(
    (total, count) => total + count,
    0,
  );
  return {
    population,
    availableWorkers,
    demand,
    assigned,
    vacancies,
    payroll: assignedWorkers * WAGE_RATE[policy.wageLevel],
  };
}

import { describe, expect, it } from "vitest";

import { applyCommand, createWorld, migrationAttractiveness } from "./index";

describe("工资与民心共同决定流民迁入", () => {
  it("三档工资提供明确吸引力修正并使用统一门槛", () => {
    expect(migrationAttractiveness(50, "low")).toEqual({
      score: 30,
      wageModifier: -20,
      canMigrate: false,
    });
    expect(migrationAttractiveness(40, "standard").canMigrate).toBe(true);
    expect(migrationAttractiveness(20, "high")).toEqual({
      score: 40,
      wageModifier: 20,
      canMigrate: true,
    });
  });

  it("低民心常薪时宅基地无人来，提高工资后才从城门出现", () => {
    const world = createWorld();
    applyCommand(world, {
      seq: 1,
      type: "build",
      buildingTypeId: "house",
      x: 1,
      y: 14,
      rotation: 0,
    });
    applyCommand(world, {
      seq: 2,
      type: "build-road-path",
      tiles: [{ x: 0, y: 15 }],
    });
    world.economy.sentiment = 35;

    applyCommand(world, { seq: 3, type: "advance-time", ticks: 1 });
    expect(world.migrants).toHaveLength(0);

    applyCommand(world, {
      seq: 4,
      type: "set-labor-policy",
      wageLevel: "high",
      priorities: ["agriculture", "commerce", "services"],
    });
    applyCommand(world, { seq: 5, type: "advance-time", ticks: 1 });
    expect(world.migrants).toEqual([
      { houseId: 1, x: 0, y: 15, state: "walking" },
    ]);
  });
});
